export type ExpandedCatalogEntry = {
  symbol: string;
  name: string;
  category: CatalogCategory;
  sector?: string;
  exchange?: string;
  tier?: LiquidityTier;
  leveraged?: boolean;
  assetType?: AssetType;
};

function entry(
  symbol: string,
  name: string,
  category: CatalogCategory,
  opts: Omit<ExpandedCatalogEntry, "symbol" | "name" | "category"> = {},
): ExpandedCatalogEntry {
  return { symbol, name, category, ...opts };
}

